UPDATE ntss.sys_facility_setting SET description='・補液計算優先項目：濾過率から算出</br>・濾過率</br>・ヘマトクリット</br>・総タンパク</br>装置設定デフォルトマスタおよび装置設定にて上記項目の表示/非表示を切り替えます。</br>尚、補液計算優先項目にて「濾過率から算出」をしている状態で当設定をＯＦＦにした場合、補液計算優先項目は「補液速度算出」に設定されます。</br>ＯＮ：上記内容を表示する</br>ＯＦＦ：上記内容を非表示にする。' WHERE facility_setting_no='3114';
UPDATE ntss.sys_facility_setting SET description='・補液計算優先項目-補液比率</br>・補液比率</br>装置設定デフォルトマスタおよび装置設定にて上記項目の表示/非表示を切り替えます。</br>尚、補液計算優先項目にて「補液比率」をしている状態で当設定をＯＦＦにした場合、補液計算優先項目は「補液速度算出」に設定されます。</br>ＯＮ：上記内容を表示する</br>ＯＦＦ：上記内容を非表示にする。' WHERE facility_setting_no='3113';